#!/usr/bin/env bash
# =============================================================================
# check-requirements-lock.sh — requirements.lock is complete and agrees with
# requirements.txt, including release hashes verified against PyPI.
#
# requirements.txt holds the DIRECT pins; requirements.lock (generated by
# tools/gen-requirements-lock.py) is what every installer uses with
# `pip --require-hashes`. This gate refuses a lock that has drifted from the
# pins, an entry that is not an exact == pin, an entry with no hash, a hash
# that is not 64 hex characters, or a duplicate package. It checks STRUCTURE
# and AGREEMENT, then the resolved package set and published target hashes.
#
#   bash tools/check-requirements-lock.sh [--root DIR]
#
# Exit: 0 consistent · 1 not · 3 could not run or could not verify (offline
# is 3 unless TM_LOCK_OFFLINE_OK=1 accepts a structure-only result).
#
# Copyright (c) 2025-2026 James Rodman. All Rights Reserved.
# =============================================================================
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[[ "${1:-}" == "--root" ]] && ROOT="${2:-}"
PY="${PYTHON:-python3}"
command -v "$PY" >/dev/null 2>&1 || PY=python
command -v "$PY" >/dev/null 2>&1 || { echo "check-requirements-lock: no python found" >&2; exit 3; }

# One parse of the lock, shared by every check below (round 10, gatekeeper
# B1): the structure check writes the entries it accepted to ${JDIR}; the
# PyPI fetch and the hash check read THAT list, never the lock again. A second
# parser that disagreed with this one (it did not strip a trailing comment)
# silently skipped entries while the verdict counted what was left.
JDIR="$(mktemp -d "${TMPDIR:-/tmp}/tm-lockjson.XXXXXX")" || { echo "check-requirements-lock: mktemp failed" >&2; exit 3; }
trap 'rm -rf -- "$JDIR"' EXIT
JDIR_PY="$(cygpath -m "$JDIR" 2>/dev/null || printf '%s' "$JDIR")"

"$PY" - "$(cygpath -m "$ROOT" 2>/dev/null || printf '%s' "$ROOT")" "$JDIR_PY" <<'PYCHK'
import json, os, re, sys
root, jdir = sys.argv[1], sys.argv[2]
def norm(n): return re.sub(r"[-_.]+", "-", n).lower()
# pip's own requirements-file rules (pip._internal.req.req_file): a line
# ending in a backslash continues onto the next unless it is a comment line;
# the joined line then loses everything from a "#" at its start or after
# whitespace. A "#" glued to a token is NOT a comment to pip, nor here.
COMMENT = re.compile(r"(^|\s+)#.*$")
def logical_lines(text):
    buf = []
    for line in text.splitlines():
        if not line.endswith("\\") or COMMENT.match(line):
            if COMMENT.match(line):
                line = " " + line
            if buf:
                buf.append(line); yield "".join(buf); buf = []
            else:
                yield line
        else:
            buf.append(line.strip("\\"))
    if buf:
        yield "".join(buf)
req = os.path.join(root, "requirements.txt"); lock = os.path.join(root, "requirements.lock")
if not os.path.isfile(lock):
    print("FAIL: requirements.lock is missing — the installers use it with --require-hashes"); sys.exit(1)
pins = {}
for line in open(req, encoding="utf-8"):
    line = line.split("#")[0].strip()
    if "==" in line:
        n, v = line.split("==", 1); pins[norm(n)] = v.strip()
if not pins:
    print("FAIL: no == pins in requirements.txt"); sys.exit(1)
text = open(lock, encoding="utf-8").read().replace("\r\n", "\n")
entries, parsed, fail = {}, [], 0
for line in logical_lines(text):
    line = COMMENT.sub("", line).strip()
    if not line:
        continue
    m = re.match(r"^([A-Za-z0-9._-]+)==([^\s]+)((?:\s+--hash=sha256:\S+)*)\s*$", line)
    if not m:
        print("FAIL: requirements.lock: not an exact pin with hashes: %s" % line[:80]); fail += 1; continue
    name, ver, hs = norm(m.group(1)), m.group(2), re.findall(r"--hash=sha256:(\S+)", m.group(3))
    if name in entries:
        print("FAIL: %s appears twice in requirements.lock" % name); fail += 1
    if not hs:
        print("FAIL: %s==%s has no --hash" % (name, ver)); fail += 1
    bad = [h for h in hs if not re.fullmatch(r"[0-9a-f]{64}", h)]
    if bad:
        print("FAIL: %s has a malformed hash: %s" % (name, bad[0][:20])); fail += 1
    entries[name] = ver
    parsed.append({"name": m.group(1), "version": ver, "hashes": hs})
for n, v in sorted(pins.items()):
    if n not in entries:
        print("FAIL: requirements.txt pins %s==%s but requirements.lock does not carry it" % (n, v)); fail += 1
    elif entries[n] != v:
        print("FAIL: %s is %s in requirements.txt but %s in requirements.lock — regenerate the lock"
              % (n, v, entries[n])); fail += 1
if fail:
    print("check-requirements-lock: %d problem(s)." % fail); sys.exit(1)
with open(os.path.join(jdir, "entries.json"), "w", encoding="utf-8") as f:
    json.dump(parsed, f)
with open(os.path.join(jdir, "entries.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("".join("%s==%s\n" % (e["name"], e["version"]) for e in parsed))
print("check-requirements-lock: %d packages locked (%d direct pins agree), every one hash-pinned."
      % (len(entries), len(pins)))
PYCHK
rc=$?
[[ $rc -eq 0 ]] || exit "$rc"

# ── online verification (round 8 completeness; round 9 hashes) ──────────────
# The checks above prove STRUCTURE and AGREEMENT with the direct pins. They
# cannot see a transitive package the lock simply lacks, nor a hash that was
# dropped or altered. Both need PyPI.
#
# OFFLINE (round 9, gatekeeper B2): the gate used to print "NOT verified" and
# exit 0, so the verdict and the exit code disagreed. Offline is now exit 3,
# "could not verify". TM_LOCK_OFFLINE_OK=1 is the one explicit way to accept a
# structure-only result — for test fixtures that are about structure alone.
GEN="${ROOT}/tools/gen-requirements-lock.py"
[[ -f "$GEN" ]] || GEN="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/gen-requirements-lock.py"
if ! command -v curl >/dev/null 2>&1 || ! curl -sfI --max-time 8 -o /dev/null https://pypi.org/simple/pip/; then
    if [[ "${TM_LOCK_OFFLINE_OK:-}" == "1" ]]; then
        echo "check-requirements-lock: PASS (structure and agreement only) — completeness and hashes NOT verified (offline; TM_LOCK_OFFLINE_OK=1)."
        exit 0
    fi
    echo "check-requirements-lock: COULD NOT VERIFY — PyPI is unreachable, so lock completeness and the hashes are NOT verified (offline). Exit 3."
    exit 3
fi

# 1. Completeness: the resolved name==version set, from the lock's own
#    generator (--check-set compares name==version, not the hash lists).
out="$("$PY" "$GEN" --check-set --root "$(cygpath -m "$ROOT" 2>/dev/null || printf '%s' "$ROOT")" 2>&1)"
crc=$?
out="$(grep -v '^\[notice\]' <<<"$out" | sed '/^$/d')"
case "$crc" in
    0) echo "check-requirements-lock: ${out##*$'\n'}" ;;
    1) printf '%s\n' "$out"; echo "check-requirements-lock: FAIL — the lock does not cover the resolved set; regenerate it."; exit 1 ;;
    *) printf '%s\n' "$out"; echo "check-requirements-lock: COULD NOT VERIFY — lock completeness (resolution failed, exit ${crc}). Exit 3."; exit 3 ;;
esac

# 2. Hashes (round 9, gatekeeper B2: a dropped or altered hash stayed GREEN).
#    For every name==version in the lock, PyPI's JSON for that exact release:
#      * every hash in the lock must be one PyPI published for it;
#      * ALL hashes for files matching the target must be present (at least one).
#        (CPython 3.12, x86_64 glibc): a cp312 or abi3 manylinux x86_64
#        wheel, or a py3-none-any wheel. This catches a dropped target hash
#        even when another target hash remains. Non-target files are optional;
#        adding those on PyPI cannot turn the gate red. A new target file does
#        require regeneration (deliberately; rare for a fixed release).
#    Fetched with curl (one file per release), judged by python.
#    The releases are the structure check's entries (entries.txt), so a line
#    this loop could not parse cannot quietly go unfetched.
nfetch=0
while IFS= read -r nv; do
    n="${nv%%==*}"; v="${nv#*==}"
    if ! curl -sf --max-time 30 -o "${JDIR}/${n}==${v}.json" "https://pypi.org/pypi/${n}/${v}/json"; then
        echo "check-requirements-lock: COULD NOT VERIFY — PyPI did not answer for ${n}==${v}. Exit 3."
        exit 3
    fi
    nfetch=$((nfetch+1))
done < "${JDIR}/entries.txt"
[[ $nfetch -gt 0 ]] || { echo "check-requirements-lock: COULD NOT VERIFY — no release was fetched. Exit 3."; exit 3; }

"$PY" - "$JDIR_PY" "$nfetch" <<'PYHASH'
import json, os, re, sys
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
jdir, nfetch = sys.argv[1], int(sys.argv[2])
entries = json.load(open(os.path.join(jdir, "entries.json"), encoding="utf-8"))

def target(fn):
    """A wheel pip would choose on CPython 3.12 / x86_64 glibc."""
    if not fn.endswith(".whl"):
        return False
    parts = fn[:-4].split("-")
    if len(parts) < 5:
        return False
    py, abi, plat = parts[-3], parts[-2], parts[-1]
    pys, plats = py.split("."), plat.split(".")
    if "py3" in pys and abi == "none" and plat == "any":
        return True
    if "cp312" in pys and abi == "cp312":
        ok = True
    elif abi == "abi3":
        ok = any(re.fullmatch(r"cp3(\d+)", p) and int(p[3:]) <= 12 for p in pys)
    else:
        ok = False
    # Ubuntu 24.04's glibc is 2.39; newer baselines cannot run on the target.
    def manylinux(p):
        if p in {"manylinux1_x86_64", "manylinux2010_x86_64", "manylinux2014_x86_64"}:
            return True
        m = re.fullmatch(r"manylinux_2_(\d+)_x86_64", p)
        return bool(m and 5 <= int(m.group(1)) <= 39)
    return ok and any(manylinux(p) for p in plats)

fail = unver = 0
n_ok = n_judged = 0
for ent in entries:
    name, ver, hs = ent["name"], ent["version"], ent["hashes"]
    path = os.path.join(jdir, "%s==%s.json" % (name, ver))
    try:
        meta = json.load(open(path, encoding="utf-8"))
        files = meta["urls"]
        published = {f["digests"]["sha256"] for f in files}
        required = {f["digests"]["sha256"]: f["filename"] for f in files
                    if target(f["filename"])}
    except Exception as e:
        print("COULD NOT VERIFY: %s==%s — PyPI's answer could not be read (%s)" % (name, ver, e.__class__.__name__))
        unver += 1
        continue
    n_judged += 1
    if not published:
        print("FAIL: %s==%s — PyPI publishes no files for this release" % (name, ver)); fail += 1; continue
    foreign = [h for h in hs if h not in published]
    for h in foreign:
        print("FAIL: %s==%s — hash %s... is not one PyPI published for this release" % (name, ver, h[:16]))
    fail += len(foreign)
    if not required:
        print("FAIL: %s==%s — no hash for a wheel pip would choose on the target (cp312/abi3 manylinux x86_64 or py3-none-any)" % (name, ver))
        fail += 1
    else:
        n_ok += 1
    for h in sorted(required.keys() - set(hs)):
        print("FAIL: %s==%s — missing target wheel hash %s (%s)" % (name, ver, h, required[h]))
        fail += 1
if unver:
    print("check-requirements-lock: COULD NOT VERIFY — %d release(s) unreadable. Exit 3." % unver); sys.exit(3)
# Coverage (round 10, gatekeeper B1): EVERY entry the structure check counted
# was fetched and judged. A shortfall is a failure, never a skip.
if not (n_judged == nfetch == len(entries)):
    print("check-requirements-lock: FAIL — the lock has %d entries but %d were fetched and %d hash-checked."
          % (len(entries), nfetch, n_judged)); sys.exit(1)
if fail:
    print("check-requirements-lock: FAIL — %d hash problem(s)." % fail); sys.exit(1)
if n_ok == 0:
    print("check-requirements-lock: COULD NOT VERIFY — no lock entry was checked. Exit 3."); sys.exit(3)
print("check-requirements-lock: PASS — %d releases: every hash is one PyPI published, and all target wheel hashes are present." % n_ok)
PYHASH
